import{_ as t}from"./chunks/dashboard.Dpem_9-E.js";import{_ as a,o as r,c as o,a3 as n}from"./chunks/framework.Ki30n65y.js";const y=JSON.parse('{"title":"What is DepGate?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is-depgate.md","filePath":"guide/what-is-depgate.md"}'),i={name:"guide/what-is-depgate.md"};function s(d,e,l,c,h,p){return r(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="what-is-depgate" tabindex="-1">What is DepGate? <a class="header-anchor" href="#what-is-depgate" aria-label="Permalink to &quot;What is DepGate?&quot;">​</a></h1><p>DepGate is a dependency gateway. It sits between your package managers and the public registries they download from, and decides, version by version, what is allowed into your organization.</p><p>Developers and build pipelines point npm, pip, Maven, Go, NuGet, Cargo, Composer or RubyGems at DepGate instead of the public registry. DepGate fetches the package from upstream, checks it against your security policies, and either serves it or refuses it with a clear reason. Nothing reaches a laptop or a build without passing through that check.</p><p><img src="'+t+'" alt="The DepGate dashboard"></p><h2 id="why-a-gateway" tabindex="-1">Why a gateway <a class="header-anchor" href="#why-a-gateway" aria-label="Permalink to &quot;Why a gateway&quot;">​</a></h2><p>Open-source packages are the largest part of most applications, and the easiest way in for an attacker. A compromised maintainer account, a typosquatted name, or a package that impersonates an internal one can reach thousands of builds within hours. Scanning after installation is too late: install scripts have already run.</p><p>DepGate moves the decision to the moment of download:</p><ul><li><strong>Known malware never downloads.</strong> DepGate checks every package against a continuously synced feed of malicious packages.</li><li><strong>Risky versions fail with a reason.</strong> A blocked download returns HTTP 403 with the policy and the reason that matched, and Package check points the developer at the newest allowed version.</li><li><strong>Your rules apply everywhere at once.</strong> One policy covers every developer, every CI runner and every ecosystem you choose.</li><li><strong>Every block is recorded.</strong> Security and compliance teams can answer &quot;who tried to install what, and which policy stopped it?&quot;, and stream every event to their SIEM.</li></ul><h2 id="key-capabilities" tabindex="-1">Key capabilities <a class="header-anchor" href="#key-capabilities" aria-label="Permalink to &quot;Key capabilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>What it gives you</th></tr></thead><tbody><tr><td><strong>Eight ecosystems, one gateway</strong></td><td>npm, PyPI, Maven, Go modules, NuGet, Cargo, Composer and RubyGems, each on its own URL.</td></tr><tr><td><strong>Malware blocking</strong></td><td>A synced feed of known-malicious packages, plus your own entries and overrides.</td></tr><tr><td><strong>Policy engine</strong></td><td>Rules for vulnerabilities (CVSS score and EPSS exploit likelihood), licenses, release age, pre-releases, project health (OpenSSF Scorecard) and named packages.</td></tr><tr><td><strong>Monitor mode</strong></td><td>Try a policy on real traffic without blocking anything, then enforce it with confidence.</td></tr><tr><td><strong>Exceptions and waivers</strong></td><td>Time-bound overrides. Developers request them; the security team approves them.</td></tr><tr><td><strong>Namespace protection</strong></td><td>Defends against dependency confusion by serving your internal names only from internal registries.</td></tr><tr><td><strong>Repositories</strong></td><td>Proxy public registries and your internal ones, and combine them behind a single URL.</td></tr><tr><td><strong>Package check</strong></td><td>A self-service page that tells developers which versions they can use, and why.</td></tr><tr><td><strong>Artifact cache</strong></td><td>Package files from public registries kept on local disk, so repeat installs are fast and keep working during a registry outage.</td></tr><tr><td><strong>Decision Ledger and Audit Log</strong></td><td>Every refused download, and every change a person made, with who did it and when.</td></tr><tr><td><strong>Single sign-on</strong></td><td>Sign in with your OpenID Connect or SAML identity provider. Roles stay in DepGate.</td></tr><tr><td><strong>Log streaming, webhooks and REST API</strong></td><td>Stream events to Splunk, Datadog, Elastic, Sumo Logic, Syslog or any HTTP endpoint, send alerts to chat, and automate everything the web interface does.</td></tr></tbody></table><h2 id="who-uses-depgate" tabindex="-1">Who uses DepGate <a class="header-anchor" href="#who-uses-depgate" aria-label="Permalink to &quot;Who uses DepGate&quot;">​</a></h2><ul><li><strong>Security teams</strong> define policies, review waivers and investigate incidents.</li><li><strong>Platform and DevOps engineers</strong> run DepGate, connect internal registries and wire it into CI/CD.</li><li><strong>Developers</strong> install packages exactly as before, and use Package check when something is blocked.</li><li><strong>Compliance and legal teams</strong> enforce license rules and use the Decision Ledger as evidence.</li></ul><h2 id="deployment-model" tabindex="-1">Deployment model <a class="header-anchor" href="#deployment-model" aria-label="Permalink to &quot;Deployment model&quot;">​</a></h2><p>DepGate is self-hosted: one container image, backed by PostgreSQL and Redis, that runs inside your network, including networks with their own certificate authority and no direct internet access. <a href="./architecture">Architecture</a> shows the components and real-world deployment scenarios, including working alongside JFrog Artifactory and Sonatype Nexus.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./architecture">Architecture</a>: where DepGate fits, what it stops, and real-world deployment scenarios.</li><li><a href="./how-it-works">How DepGate works</a>: the request flow, the order of checks and the main concepts.</li><li><a href="./quick-start">Quick start</a>: run DepGate on one machine and block your first package.</li><li><a href="/depgate/install/requirements">Requirements</a>: plan a production installation.</li></ul>',16)])])}const m=a(i,[["render",s]]);export{y as __pageData,m as default};
